/**
 * Transfers vote-kick feature settings persisted in the shared feature configuration table.
 */
export type VoteKickFeatureSettingsDto = {
    /**
     * Indicates whether the vote-kick feature is enabled.
     */
    isEnabled?: boolean;
    /**
     * Primary chat command name. Defaults to "votekick" when null.
     */
    commandName?: string | null;
    /**
     * Additional aliases accepted alongside CommandName.
     */
    commandAliases?: Array<string> | null;
    /**
     * Minimum number of online players required before a vote can be initiated.
     */
    minOnlinePlayers?: number;
    /**
     * Duration in seconds a vote stays open before automatically closing.
     */
    voteDurationSeconds?: number;
    /**
     * Percentage of online players whose yes vote is required for the vote to pass (0–100).
     */
    passThresholdPercent?: number;
    /**
     * Per-initiator cooldown in seconds after a vote concludes (regardless of outcome).
     */
    initiatorCooldownSeconds?: number;
    /**
     * Immunity window in seconds before a successfully kicked player can be re-targeted.
     */
    targetImmunitySeconds?: number;
    /**
     * Reason shown to the kicked player. Supports {yes_count}.
     */
    kickReason?: string | null;
    /**
     * Broadcast on vote start. Supports {target}, {initiator}, and {duration}.
     */
    voteStartedMessage?: string | null;
    /**
     * Broadcast when the vote passes and the player is kicked. Supports {target} and {yes_count}.
     */
    votePassedMessage?: string | null;
    /**
     * Broadcast when the vote fails. Supports {target}.
     */
    voteFailedMessage?: string | null;
    /**
     * Private reply when a player attempts to vote a second time.
     */
    alreadyVotedMessage?: string | null;
    /**
     * Private reply when the initiator's cooldown has not expired. Supports {seconds}.
     */
    cooldownMessage?: string | null;
    /**
     * Private reply when the target is a server admin and cannot be kicked.
     */
    cannotKickAdminMessage?: string | null;
    /**
     * Private reply when the named target is not found online. Supports {name}.
     */
    targetNotFoundMessage?: string | null;
    /**
     * Broadcast when the target disconnects while the vote is active.
     */
    targetAlreadyGoneMessage?: string | null;
    /**
     * Private reply when a vote is already in progress.
     */
    alreadyActiveMessage?: string | null;
    /**
     * Private reply when the command is invoked without a target name argument.
     */
    usageTipMessage?: string | null;
    /**
     * Private reply when there are too few online players. Supports {required}.
     */
    notEnoughPlayersMessage?: string | null;
    /**
     * Broadcast showing vote tallies after each cast. Supports {yes}, {no}, {needed}.
     */
    voteProgressMessage?: string | null;
};

