export type OAuthTokenData = {
    /**
     * User login with form data
     */
    body: {
        /**
         * The grant type being used (e.g., password for username/password login, or refresh_token for refreshing an existing token).
         */
        grant_type: string;
        /**
         * The user's username. Required when grant_type is password.
         */
        username?: string;
        /**
         * The user's password. Required when grant_type is password.
         */
        password?: string;
        /**
         * The refresh token. Required when grant_type is refresh_token.
         */
        refresh_token?: string;
    };
    path?: never;
    query?: never;
    url: '/api/oauth/token';
};

export type OAuthTokenErrors = {
    /**
     * Authentication error.
     */
    400: {
        error: string;
        error_description: string;
    };
};

export type OAuthTokenError = OAuthTokenErrors[keyof OAuthTokenErrors];

export type OAuthTokenResponses = {
    /**
     * Authentication token and meta data.
     */
    200: {
        access_token: string;
        token_type: string;
        expires_in: number;
        refresh_token?: string;
    };
};

export type OAuthTokenResponse = OAuthTokenResponses[keyof OAuthTokenResponses];
